package net.flashlight.battery;
import fixture.Checks;import net.minecraft.world.item.ItemStack;import net.minecraft.resources.ResourceLocation;
public class ReloadChecks6{static int n;static void ok(boolean b,String m){n++;if(!b)throw new AssertionError(m);}static ItemStack s(String id,int n){return new ItemStack(ResourceLocation.parse(id),n);}public static class Slot{int changes;boolean may=true;public void setChanged(){changes++;}public boolean mayPickup(Object p){return may;}public boolean mayPlace(Object s){return may;}}public enum Action{PRIMARY,SECONDARY}
 public static void main(String[]args){for(int t=0;t<4;t++)for(boolean lit:new boolean[]{false,true}){var p=new Checks.Player();var lamp=s("flashlight:"+Power.TYPES[t]+(lit?"":"_off"),1);var battery=s("flashlight:battery",5);var slot=new Slot();ok(!Power.inventoryCell(p,battery,lamp,slot,Action.PRIMARY),"left click preserves ordinary inventory operation");ok(Power.inventoryCell(p,battery,lamp,slot,Action.SECONDARY),"battery can be inserted directly into inventory lamp");ok(Power.remaining(lamp)==Power.CAPACITY[t]&&battery.getCount()==4&&slot.changes==1,"exactly one battery consumed at every tier and on/off state");Power.inventoryCell(p,battery,lamp,slot,Action.SECONDARY);ok(battery.getCount()==4,"full lamp cannot consume another battery");Power.charge(lamp,0);slot.may=false;ok(!Power.inventoryCell(p,battery,lamp,slot,Action.SECONDARY)&&battery.getCount()==4,"locked/output slots cannot be modified");}
 var p=new Checks.Player();p.main=s("flashlight:battery",3);p.off=s("flashlight:tactical_off",1);Power.useBattery(p,p.main);ok(Power.remaining(p.off)==12000&&p.main.getCount()==2,"right-click battery reloads offhand lamp");p.inv.stacks[9]=s("flashlight:eco_off",1);Power.useBattery(p,p.main);ok(Power.remaining(p.inv.stacks[9])==36000&&p.main.getCount()==1,"battery use can find an uncharged inventory lamp");var client=new Checks.Player();client.world.isClientSide=true;var battery=s("flashlight:battery",2);var lamp=s("flashlight:flashlight_off",1);ok(Power.install(client,lamp,battery)&&battery.getCount()==2&&Power.remaining(lamp)==0,"client prediction cannot grant charge or consume items");ok(!Power.install(p,lamp,s("minecraft:redstone",3)),"wrong item cannot act as battery");ok(!Power.install(p,s("minecraft:iron_sword",1),battery),"battery cannot modify unrelated item");ok(!Power.install(p,lamp,s("flashlight:battery",0)),"empty stack cannot create charge");System.out.println("BATTERY_CURSOR_OFFHAND_INVENTORY_TIER_AUTHORITY_CHECKS="+n);}}
